import os
import base64
import anthropic

def extract_receipt_fields(payload, config=None):
    config = config or {}
    client = anthropic.Anthropic(api_key=config.get("api_key") or os.environ["ANTHROPIC_API_KEY"])
    image_b64 = payload.get("image_base64") or payload.get("image") or payload.get("document_base64")
    if not image_b64:
        raise ValueError("payload must include 'image_base64', 'image', or 'document_base64'")
    media_type = payload.get("media_type") or payload.get("mime_type") or "image/jpeg"
    prompt = (
        "Extract structured data from this receipt and return ONLY valid JSON with this exact schema: "
        '{"merchant": string|null, "tax": number|null, "total": number|null, '
        '"items": [{"name": string, "quantity": number|null, "price": number|null}]}. '
        "Use numeric values without currency symbols. If a field is missing, use null. "
        "Do not include any extra text."
    )
    response = client.messages.create(
        model=config.get("model", "claude-3-5-sonnet-20241022"),
        max_tokens=config.get("max_tokens", 1024),
        temperature=0,
        messages=[
            {
                "role": "user",
                "content": [
                    {
                        "type": "image",
                        "source": {
                            "type": "base64",
                            "media_type": media_type,
                            "data": image_b64,
                        },
                    },
                    {"type": "text", "text": prompt},
                ],
            }
        ],
    )
    text = "".join(
        block.text for block in response.content
        if getattr(block, "type", None) == "text"
    ).strip()
    result = __import__("json").loads(text)
    return result
